<?php
declare(strict_types=1);

$page_title = 'Gestión de Eventos TI';
require_once __DIR__.'/../../includes/load.php';
require_once __DIR__.'/../../config/app.php';
require_once __DIR__.'/bootstrap.php';
require_once __DIR__.'/importar_eventos_lib.php';
evt_schema();
require_permiso('eventos_ti', 'ver');

$autoImport = evt_import_pending_folder(__DIR__.DIRECTORY_SEPARATOR.'Log_Eventos', 50);

$filters = [
    'severity' => strtoupper(trim((string)($_GET['severity'] ?? ''))),
    'source' => strtoupper(trim((string)($_GET['source'] ?? ''))),
    'state' => strtoupper(trim((string)($_GET['state'] ?? ''))),
    'vm' => (int)($_GET['vm'] ?? 0),
    'from' => trim((string)($_GET['from'] ?? '')),
    'to' => trim((string)($_GET['to'] ?? '')),
    'q' => trim((string)($_GET['q'] ?? '')),
];
$where = ['1=1'];
if (in_array($filters['severity'], ['INFORMATIVO','ADVERTENCIA','ERROR','CRITICO'], true)) $where[] = "e.Severidad='".$db->escape($filters['severity'])."'";
if ($filters['source'] !== '') $where[] = "e.Fuente='".$db->escape($filters['source'])."'";
if (in_array($filters['state'], ['NUEVO','EN_REVISION','REVISADO','DESCARTADO','VINCULADO'], true)) $where[] = "e.Estado='".$db->escape($filters['state'])."'";
if ($filters['vm'] > 0) $where[] = 'e.IdVM='.$filters['vm'];
if (preg_match('/^\d{4}-\d{2}-\d{2}$/', $filters['from'])) $where[] = "e.FechaEvento>='".$db->escape($filters['from'])." 00:00:00'";
if (preg_match('/^\d{4}-\d{2}-\d{2}$/', $filters['to'])) $where[] = "e.FechaEvento<='".$db->escape($filters['to'])." 23:59:59'";
if ($filters['q'] !== '') {
    $q = $db->escape($filters['q']);
    $where[] = "(e.Titulo LIKE '%{$q}%' OR e.Mensaje LIKE '%{$q}%' OR e.CodigoEvento LIKE '%{$q}%' OR e.HostOrigen LIKE '%{$q}%' OR e.IPOrigen LIKE '%{$q}%')";
}

$events = find_by_sql("SELECT e.*,v.NombreVM,m.Host,a.NombreAplicacion,t.Folio,t.Estado EstadoIncidencia
    FROM evt_eventos e
    LEFT JOIN maquina_virtual v ON v.IdVM=e.IdVM
    LEFT JOIN maquina m ON m.IdMaquina=COALESCE(e.IdMaquina,v.IdMaquina)
    LEFT JOIN aplicacion a ON a.IdAplicacion=e.IdAplicacion
    LEFT JOIN inc_tickets t ON t.IdTicket=e.IdIncidencia
    WHERE ".implode(' AND ', $where)."
    ORDER BY e.FechaEvento DESC,e.IdEvento DESC LIMIT 750");
$vms = find_by_sql("SELECT v.IdVM,v.NombreVM,v.IP_VM,m.Host FROM maquina_virtual v INNER JOIN maquina m ON m.IdMaquina=v.IdMaquina WHERE v.EstadoVM<>'RETIRADA' ORDER BY v.NombreVM");
$applications = find_by_sql("SELECT IdAplicacion,NombreAplicacion,Ambiente FROM aplicacion WHERE EstadoAplicacion<>'INACTIVA' ORDER BY NombreAplicacion");
$rules = find_by_sql("SELECT * FROM evt_reglas ORDER BY Activa DESC,Orden,Nombre");
$imports = find_by_sql("SELECT * FROM evt_importaciones ORDER BY FechaProceso DESC LIMIT 12");
$tickets = find_by_sql("SELECT IdTicket,Folio,Titulo,Prioridad,Estado FROM inc_tickets WHERE Estado NOT IN ('CERRADO','CANCELADO') ORDER BY FechaRegistro DESC LIMIT 250");
$sources = find_by_sql("SELECT DISTINCT Fuente FROM evt_eventos ORDER BY Fuente");
$statsRows = find_by_sql("SELECT
    SUM(Estado='NUEVO') Nuevos,
    SUM(Severidad='CRITICO' AND FechaEvento>=DATE_SUB(NOW(),INTERVAL 24 HOUR)) Criticos24,
    SUM(IdIncidencia IS NOT NULL) Vinculados,
    COUNT(DISTINCT COALESCE(IdVM,0)) FuentesVM,
    COUNT(*) Total
    FROM evt_eventos");
$stats = $statsRows[0] ?? ['Nuevos'=>0,'Criticos24'=>0,'Vinculados'=>0,'FuentesVM'=>0,'Total'=>0];
$canCreate = tiene_permiso('eventos_ti','crear');
$canEdit = tiene_permiso('eventos_ti','editar');
$exportQuery = http_build_query($filters);

$extraCss = [BASE_URL.'/assets/css/eventos_ti.css'];
include_once __DIR__.'/../../layouts/header.php';
?>

<section class="content-header pb-1"><div class="container-fluid"><div class="d-flex justify-content-between align-items-center"><h1 class="h4 mb-0"><i class="fas fa-wave-square mr-2 text-info"></i>Gestión de Eventos TI</h1><ol class="breadcrumb mb-0"><li class="breadcrumb-item"><a href="../../home.php">Inicio</a></li><li class="breadcrumb-item active">Eventos TI</li></ol></div></div></section>
