    <?php if($autoImport['processed']>0):?><div class="alert alert-success"><i class="fas fa-file-import mr-2"></i>Importación automática: <strong><?= (int)$autoImport['inserted'] ?> evento(s) nuevo(s)</strong>, <?= (int)$autoImport['duplicates'] ?> duplicado(s). Los archivos procesados fueron marcados como <code>-LEIDO</code>.</div><?php endif;?>
