iv><div class="col-md-4 text-md-right"><a href="index.php" class="btn btn-outline-secondary btn-sm"><i class="fas fa-eraser mr-1"></i>Limpiar</a><button class="btn btn-info btn-sm"><i class="fas fa-search mr-1"></i>Aplicar filtros</button><?php if($canCreate):?><button type="button" class="btn btn-success btn-sm" data-toggle="modal" data-target="#modalEvent"><i class="fas fa-plus mr-1"></i>Evento manual</button><?php endif;?></div></div></form>
            <div class="card evt-panel"><div class="card-header"><h3 class="card-title">Bandeja de eventos</h3><small class="text-muted float-right">Mostrando hasta 750 registros</small></div><div class="card-body"><div class="table-responsive"><table id="tblEvents" class="table table-hover evt-table w-100"><thead><tr><th>Fecha</th><th>Severidad</th><th>Fuente / Código</th><th>Servidor, VM o aplicación</th><th>Evento</th><th>Estado</th><th>Incidencia</th><th></th></tr></thead><tbody><?php foreach($events as $event):?><tr><td data-order="<?=evt_h($event['FechaEvento'])?>"><?=date('d/m/Y H:i:s',strtotime($event['FechaEvento']))?></td><td><span class="evt-severity <?=evt_h($event['Severidad'])?>"><?=evt_severity_label($event['Severidad'])?></span><?php if($event['RequiereIncidencia']):?><small class="d-block text-danger mt-1"><i class="fas fa-bell mr-1"></i>Revisar incidencia</small><?php endif;?></td><td><strong><?=evt_h($event['Fuente'])?></strong><span class="evt-code d-block"><?=evt_h($event['CodigoEvento']?:'Sin código')?></span></td><td><span class="evt-name"><?=evt_h($event['NombreVM']?:$event['Host']?:$event['HostOrigen']?:'No relacionado')?></span><?php if($event['IPOrigen']):?><small class="d-block text-muted"><?=evt_h($event['IPOrigen'])?></small><?php endif;?><?php if($event['NombreAplicacion']):?><small class="d-block text-info"><i class="fas fa-window-maximize mr-1"></i><?=evt_h($event['NombreAplicacion'])?></small><?php endif;?></td><td><strong><?=evt_h($event['Titulo'])?></strong><small class="d-block text-muted text-truncate" style="max-width:360px"><?=evt_h($event['Mensaje'])?></small></td><td><span class="evt-state <?=evt_h($event['Estado'])?>"><?=evt_status_label($event['Estado'])?></span></td><td><?php if($event['IdIncidencia']):?><a class="badge badge-primary" href="../incidencias/detalle.php?id=<?=(int)$event['IdIncidencia']?>"><?=evt_h($event['Folio'])?></a><small class="d-block text-muted"><?=inc_status_label($event['EstadoIncidencia'])?></small><?php else:?><span class="text-muted">—</span><?php endif;?></td><td><a href="detalle.php?id=<?=(int)$event['IdEvento']?>" class="btn btn-outline-info btn-sm" title="Revisar evento"><i class="fas fa-eye"></i></a></td></tr><?php endforeach;?></tbody></table><?php if(!$events):?><div class="evt-empty"><i class="fas fa-check-circle"></i>No hay eventos que coincidan con los filtros.</div><?php endif;?></div></div></div>
