kbox" class="custom-control-input" id="ruleIncident" name="RequiereIncidencia" value="1"><label class="custom-control-label" for="ruleIncident">Revisar incidencia</label></div><div class="custom-control custom-checkbox"><input type="checkbox" class="custom-control-input" id="ruleActive" name="Activa" value="1" checked><label class="custom-control-label" for="ruleActive">Regla activa</label></div></div><div class="col-12 form-group mb-0"><label>Descripción</label><textarea name="Descripcion" class="form-control"></textarea></div></div></div></div><div class="modal-footer"><button type="button" class="btn btn-light" data-dismiss="modal">Cancelar</button><button class="btn btn-info">Guardar regla</button></div></form></div></div></div><?php endif;?>

